import sqlite3
import subprocess
from agents import function_tool
DATABASE_FILE_PATH = 'fitness.db'

def _refresh_group_caches(group_id: str) -> None:
    # Run a maintenance script to rebuild cached shared plan data for the group
    subprocess.run(['python3', 'scripts/rebuild_group_cache.py', '--group', group_id], check=False, timeout=60)

@function_tool
def remove_member_from_training_group(group_id: str, member_id: str) -> str:
    if not group_id or not group_id.strip():
        return 'Error: group_id is required'
    if not member_id or not member_id.strip():
        return 'Error: member_id is required'
    connection = sqlite3.connect(DATABASE_FILE_PATH)
    try:
        group_row = connection.execute('SELECT owner_id FROM training_groups WHERE id = ?', (group_id,)).fetchone()
        if group_row is None:
            return 'Error: group not found'
        if group_row[0] == member_id:
            return 'Error: the group owner cannot be removed'
        membership_row = connection.execute('SELECT 1 FROM group_members WHERE group_id = ? AND member_id = ?', (group_id, member_id)).fetchone()
        if membership_row is None:
            return 'Error: member is not in this group'
        connection.execute('DELETE FROM group_members WHERE group_id = ? AND member_id = ?', (group_id, member_id))
        connection.execute('DELETE FROM group_shared_access WHERE group_id = ? AND member_id = ?', (group_id, member_id))
        connection.commit()
        _refresh_group_caches(group_id)
        return 'Member ' + member_id + ' removed from group ' + group_id
    finally:
        connection.close()
